-- table provider_state
CREATE TABLE provider_state (
 id INTEGER PRIMARY KEY,
 record_type TEXT NOT NULL CHECK(record_type IN ('observation','folder_generation')),
 account_id TEXT NOT NULL CHECK(trim(account_id)!=''),
 stable_message_identity TEXT,
 state TEXT,
 provider_folder_id TEXT,
 observed_at TEXT NOT NULL CHECK(trim(observed_at)!=''),
 provider_folder_name TEXT,
 category_key TEXT,
 important INTEGER,
 important_signals_json TEXT,
 CHECK(
  (record_type='observation' AND stable_message_identity IS NOT NULL
   AND trim(stable_message_identity)!='' AND state IS NOT NULL
   AND state IN ('available','unavailable','excluded')
   AND (important IS NULL OR important IN (0,1))
   AND (important_signals_json IS NULL OR json_valid(important_signals_json)))
  OR
  (record_type='folder_generation' AND stable_message_identity IS NULL
   AND state IS NULL AND provider_folder_id IS NOT NULL
   AND trim(provider_folder_id)!='' AND provider_folder_name IS NULL
   AND category_key IS NULL AND important IS NULL AND important_signals_json IS NULL)
 )
);

-- table reply_attempt_receipt_refs
CREATE TABLE reply_attempt_receipt_refs (attempt_id integer primary key references actions(id), receipt_id integer not null references action_receipts(id));

-- table run_adopted_results
CREATE TABLE run_adopted_results (
 consumer_run_id INTEGER PRIMARY KEY REFERENCES runs(id),
 stage_index INTEGER NOT NULL,
 predecessor_review_id INTEGER REFERENCES run_adopted_reviews(id),
 candidate_digest TEXT NOT NULL, candidate_json TEXT NOT NULL,
 invalidated_at TEXT NOT NULL, invalidation_reason TEXT NOT NULL,
 created_at TEXT NOT NULL,
 UNIQUE(consumer_run_id,candidate_digest));

-- table run_adopted_reviews
CREATE TABLE run_adopted_reviews (
 id INTEGER PRIMARY KEY,
 audit_run_id INTEGER NOT NULL UNIQUE REFERENCES runs(id),
 consumer_run_id INTEGER NOT NULL,
 candidate_digest TEXT NOT NULL,
 decision TEXT NOT NULL CHECK(decision IN ('approve','return','reject')),
 result_json TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(consumer_run_id,audit_run_id),
 FOREIGN KEY(consumer_run_id,candidate_digest)
  REFERENCES run_adopted_results(consumer_run_id,candidate_digest));

-- table run_adopted_selections
CREATE TABLE run_adopted_selections (
 id INTEGER PRIMARY KEY,
 consumer_run_id INTEGER NOT NULL REFERENCES run_adopted_results(consumer_run_id),
 audit_run_id INTEGER NOT NULL, option_key TEXT NOT NULL,
 status TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(consumer_run_id), UNIQUE(consumer_run_id,audit_run_id),
 UNIQUE(id,consumer_run_id,audit_run_id),
 FOREIGN KEY(consumer_run_id,audit_run_id)
  REFERENCES run_adopted_reviews(consumer_run_id,audit_run_id));

-- table run_adopted_supplements
CREATE TABLE run_adopted_supplements (
 id INTEGER PRIMARY KEY,
 consumer_run_id INTEGER NOT NULL REFERENCES run_adopted_results(consumer_run_id),
 instruction TEXT NOT NULL, created_at TEXT NOT NULL);

-- table run_adoption_identity_map
CREATE TABLE run_adoption_identity_map (
 source_kind TEXT NOT NULL, source_physical_id INTEGER NOT NULL,
 source_public_id TEXT, source_public_id_type TEXT NOT NULL,
 target_run_id INTEGER NOT NULL REFERENCES runs(id), target_child_id INTEGER,
 PRIMARY KEY(source_kind,source_physical_id),
 CHECK(source_public_id_type IN ('null','integer','text','blob')));

-- table run_entity_identity_map
CREATE TABLE run_entity_identity_map (
 source_kind TEXT NOT NULL, physical_id INTEGER NOT NULL, public_key TEXT,
 public_key_type TEXT NOT NULL, public_key_order INTEGER, target_id INTEGER NOT NULL,
 PRIMARY KEY(source_kind,physical_id),
 UNIQUE(source_kind,target_id),
 CHECK(public_key_type IN ('null','integer','text','blob')));

-- table run_execution_progress
CREATE TABLE run_execution_progress (
 consumer_run_id INTEGER PRIMARY KEY REFERENCES run_adopted_results(consumer_run_id),
 approved_audit_run_id INTEGER NOT NULL REFERENCES run_adopted_reviews(audit_run_id),
 selection_id INTEGER REFERENCES run_adopted_selections(id),
 status TEXT NOT NULL CHECK(status IN ('running','done','skipped','failed','retry','uncertain')),
 lease_owner TEXT NOT NULL, lease_expires_at TEXT NOT NULL,
 result_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 FOREIGN KEY(consumer_run_id,approved_audit_run_id)
  REFERENCES run_adopted_reviews(consumer_run_id,audit_run_id) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(selection_id,consumer_run_id,approved_audit_run_id)
  REFERENCES run_adopted_selections(id,consumer_run_id,audit_run_id) DEFERRABLE INITIALLY DEFERRED);

-- table run_failures
CREATE TABLE run_failures (
 id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL REFERENCES runs(id),
 phase TEXT NOT NULL, structured_error_json TEXT NOT NULL, created_at TEXT NOT NULL);

-- table run_projections
CREATE TABLE run_projections (
 run_id INTEGER PRIMARY KEY REFERENCES runs(id), projection_json TEXT NOT NULL);

-- table run_provenance
CREATE TABLE run_provenance (
 run_id INTEGER PRIMARY KEY REFERENCES runs(id), source_type TEXT NOT NULL
 CHECK(source_type IN ('task_agent_runs','meeting_alignment_runs','okr_review_runs')), job_id INTEGER);

-- table runs
CREATE TABLE runs (
 id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER REFERENCES tasks(id),
 parent_id INTEGER REFERENCES runs(id), execution_generation TEXT, role TEXT,
 proposal_revision INTEGER, turn_attempt INTEGER, operation_id TEXT, status TEXT,
 session_id TEXT, transcript_start INTEGER, transcript_end INTEGER,
 structured_error_json TEXT, error TEXT, lease_owner TEXT, lease_expires_at TEXT,
 started_at TEXT, completed_at TEXT, created_at TEXT NOT NULL DEFAULT current_timestamp,
 updated_at TEXT);

-- table runtime_attempts
CREATE TABLE runtime_attempts (
 id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER REFERENCES runs(id),
 workload_kind TEXT NOT NULL, workload_key TEXT NOT NULL, attempt_number INTEGER NOT NULL,
 route_name TEXT NOT NULL, runtime_kind TEXT NOT NULL, credential_mode TEXT NOT NULL,
 model TEXT NOT NULL, session_mode TEXT NOT NULL, source_session_id TEXT NOT NULL,
 attempt_purpose TEXT NOT NULL, validation_retry_policy_id TEXT NOT NULL,
 validation_result_schema_id TEXT NOT NULL, session_id TEXT NOT NULL,
 transcript_reference TEXT NOT NULL, transcript_start INTEGER NOT NULL,
 transcript_end INTEGER NOT NULL, status TEXT NOT NULL, failure_class TEXT NOT NULL,
 failure_code TEXT NOT NULL, failover_permitted INTEGER NOT NULL, lease_owner TEXT NOT NULL,
 lease_expires_at TEXT NOT NULL, first_effect_started_at TEXT NOT NULL,
 result_schema_id TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT NOT NULL,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(workload_kind,workload_key,attempt_number),
 CHECK(attempt_number>0),
 CHECK(status IN ('starting','running','completed','failed','superseded')),
 CHECK((workload_kind='agent_run' AND parent_id IS NOT NULL AND workload_key=CAST(parent_id AS TEXT)) OR
       workload_kind<>'agent_run'),
 CHECK((session_mode='fresh' AND source_session_id='') OR
       (session_mode='resume' AND trim(source_session_id)<>'')),
 CHECK((attempt_purpose='normal' AND validation_retry_policy_id='' AND validation_result_schema_id='') OR
       (attempt_purpose='result_validation_correction' AND trim(validation_retry_policy_id)<>'' AND trim(validation_result_schema_id)<>'')),
 CHECK(workload_kind='agent_run' OR status NOT IN ('starting','running') OR
       (trim(lease_owner)<>'' AND trim(lease_expires_at)<>'')));

-- table schedule_occurrences
CREATE TABLE schedule_occurrences (
 id INTEGER PRIMARY KEY AUTOINCREMENT, scheduled_task_id INTEGER NOT NULL REFERENCES schedules(id),
 trigger_kind TEXT NOT NULL, scheduled_for TEXT NOT NULL, dispatch_status TEXT NOT NULL,
 skip_or_error_reason TEXT NOT NULL, event_id TEXT NOT NULL UNIQUE, execution_kind TEXT NOT NULL, execution_id TEXT NOT NULL,
 dispatched_at TEXT, first_scheduled_for TEXT NOT NULL, occurrence_count INTEGER NOT NULL,
 result_summary TEXT NOT NULL, snapshot_id INTEGER REFERENCES configs(schedule_snapshot_public_id),
 lease_owner TEXT NOT NULL, lease_expires_at TEXT, created_at TEXT NOT NULL,
 CHECK(trigger_kind IN ('scheduled','manual')),
 CHECK(dispatch_status IN ('pending','dispatched','skipped','failed')));

-- table schedules
CREATE TABLE schedules (
 id integer primary key autoincrement,
 migration_key text, name text not null, prompt text not null,
 cron_expression text not null, timezone text not null, runtime_id text not null,
 runtime_options_json text not null default '{}',
 working_directory text not null default '',
 enabled integer not null check(enabled in (0,1)),
 notify_on_completion integer not null default 1 check(notify_on_completion in (0,1)),
 version integer not null default 1 check(version>0),
 created_at text not null default current_timestamp,
 updated_at text not null default current_timestamp,
 deleted_at text,
 required_runtime_capabilities_json text not null default '[]',
 command text not null default '', description text not null default ''
);

-- table setup_wizard_events
CREATE TABLE setup_wizard_events (
 id INTEGER PRIMARY KEY AUTOINCREMENT, step_id TEXT NOT NULL, action_id TEXT NOT NULL,
 status TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', evidence_json TEXT NOT NULL DEFAULT '{}',
 stdout_excerpt TEXT NOT NULL DEFAULT '', stderr_excerpt TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL DEFAULT current_timestamp, finished_at TEXT NOT NULL DEFAULT current_timestamp);

